/// C2 mastery curriculum, lessons 511-540.
class C2CapstoneCourseData {
 static List<String> _rotate(List<String> v,int a)=>List<String>.generate(v.length,(i)=>v[(i-a+v.length)%v.length]);
 static B1Question _q(String p,List<String> o,int a,String e)=>B1Question(p,_rotate(o,a),a,e);
 static B1Lesson _build(_Spec s){final n=s.number;return B1Lesson(unitId:s.unitId,globalNumber:n,title:s.title,goal:s.goal,rule:s.rule,examples:[s.sentence+' | '+s.translation,s.example],dialogue:s.dialogue,speakingTask:s.task,questions:[_q('ما المقصود بالمفهوم «${s.term}»؟',[s.meaning,'التعبير عن المكان','التعبير عن الزمن الماضي','طلب الإذن'],n%4,'المفهوم «${s.term}» يعني: ${s.meaning}.'),_q('ما الترجمة الأدق للجملة؟',[s.translation,'لم يبدأ الاجتماع بعد.','سأعود إلى المنزل غداً.','لا تتضمن الجملة هذا المعنى.'],(n+1)%4,s.translation),_q('أي مصطلح يرتبط مباشرة بالدرس؟',[s.form,'geçmiş zaman','istek kipi','yer tamlayıcısı'],(n+2)%4,s.rule),_q('ما الوظيفة التواصلية الأساسية؟',[s.functionText,'تحديد المكان فقط','تغيير زمن الجملة فقط','السؤال عن السعر'],(n+3)%4,s.functionText),_q('أي نشاط يثبت اكتساب المهارة؟',[s.task,'حفظ كلمات دون سياق','نسخ نص دون فهم','تجاهل القرائن والأدلة'],(n+1)%4,s.task)]);}
 static final List<B1Lesson> lessons=[
_Spec(unitId:'c2-u10',number:511,title:'تحليل الخطاب السياسي المقارن',goal:'تحليل الأطر والحجج والاستراتيجيات الخطابية في خطابات سياسية من سياقات مختلفة.',rule:'افصل بين مضمون الرسالة وإطارها البلاغي وافتراضاتها، وقارن المصطلحات والسياق والجمهور.',term:'söylem çerçevesi',meaning:'الإطار الخطابي',sentence:'Konuşmanın çerçevesi, seçilen kavramlar ve vurgular aracılığıyla kuruluyor.',translation:'يتشكل إطار الخطاب من خلال المفاهيم المختارة ونقاط التركيز.',form:'karşılaştırmalı söylem çözümlemesi',functionText:'تحليل الخطاب ومقارنة أطره.',task:'قارن خطابين حول القضية نفسها وحدد الأطر والحجج والافتراضات.',example:'İki konuşmanın hedef kitlesini ve söylem çerçevesini karşılaştırdım.|قارنت الجمهور المستهدف والإطار الخطابي لخطابين.',dialogue:'A: Aynı olay neden farklı anlatılıyor؟ — لماذا يُروى الحدث نفسه بصورة مختلفة؟\nB: Çünkü çerçeve ve öncelikler değişiyor. — لأن الإطار والأولويات يتغيران.'),
_Spec(unitId:'c2-u10',number:512,title:'تحليل الاستعارة المفاهيمية في الخطاب العام',goal:'كشف الاستعارات التي تنظم فهم الجمهور للمفاهيم المجردة.',rule:'حدد المجال المصدر والهدف، ثم اختبر أثر الاستعارة وما تخفيه من جوانب.',term:'kavramsal metafor',meaning:'استعارة مفاهيمية',sentence:'Bu söylemde ekonomi bir yolculuk olarak tasvir ediliyor.',translation:'يُصوَّر الاقتصاد في هذا الخطاب على أنه رحلة.',form:'metaforik çerçeve',functionText:'تحليل الاستعارات المؤثرة في فهم القضايا.',task:'استخرج خمس استعارات مفاهيمية من خطاب عام وناقش آثارها.',example:'Metaforun düşünceyi nasıl yönlendirdiğini inceledim.|درست كيف توجه الاستعارة التفكير.',dialogue:'A: Bu yalnızca süslü bir ifade mi؟ — هل هذا مجرد تعبير مزخرف؟\nB: Hayır, konuyu algılama biçimini de etkiliyor. — لا، بل يؤثر أيضاً في طريقة إدراك الموضوع.'),
_Spec(unitId:'c2-u10',number:513,title:'التعرف إلى المغالطات الحجاجية المركبة',goal:'تمييز المغالطة داخل حجة تبدو منطقية ومترابطة.',rule:'اختبر صلة الدليل بالنتيجة، وكفاية العينة، والافتراضات المخفية، والبدائل الممكنة.',term:'karmaşık safsata',meaning:'مغالطة مركبة',sentence:'Sonuç, sunulan verilerin kapsamını aştığı için gerekçelendirilmemiştir.',translation:'النتيجة غير مبررة لأنها تتجاوز نطاق البيانات المقدمة.',form:'mantık denetimi',functionText:'تدقيق الحجة وكشف القفزات المنطقية.',task:'حلل مقالة رأي وحدد ثلاث مغالطات مع تفسير أثرها.',example:'Kanıt ile sonuç arasındaki bağı ayrı ayrı değerlendirdim.|قيّمت الصلة بين الدليل والنتيجة على حدة.',dialogue:'A: Güçlü bir örnek iddiayı kanıtlar mı؟ — هل يثبت مثال قوي الادعاء؟\nB: Tek örnek genelleme için yeterli olmayabilir. — قد لا يكفي مثال واحد للتعميم.'),
_Spec(unitId:'c2-u10',number:514,title:'تحليل الصمت والحذف في النصوص',goal:'فهم المعنى الناتج عن المعلومات المحذوفة وما يفترضه النص.',rule:'حدد ما لا يقال، ومن يملك سلطة الكلام، وما الذي يتوقع النص من القارئ استنتاجه.',term:'örtük anlam',meaning:'معنى ضمني',sentence:'Metindeki suskunluk, okurun belirli bir çıkarım yapmasını bekliyor.',translation:'يتوقع الصمت في النص من القارئ أن يستنتج أمراً معيناً.',form:'söylemde eksiltme',functionText:'تحليل الحذف والصمت بوصفهما عنصرين دلاليين.',task:'حلل فقرة وحدد المعلومات المحذوفة ووظيفتها في بناء المعنى.',example:'Eksiltilen bilgilerin metindeki işlevini tartıştım.|ناقشت وظيفة المعلومات المحذوفة في النص.',dialogue:'A: Yazar neden bunu açıkça söylememiş؟ — لماذا لم يقل الكاتب ذلك صراحة؟\nB: Okurun bağlamdan çıkarmasını istemiş olabilir. — ربما أراد من القارئ استنتاجه من السياق.'),
_Spec(unitId:'c2-u10',number:515,title:'تحليل التناص والإحالات الثقافية',goal:'تتبع النصوص والإشارات السابقة التي يستدعيها خطاب جديد.',rule:'حدد الاقتباس أو التلميح أو المحاكاة، وفسر وظيفة الإحالة لدى الجمهور المقصود.',term:'metinlerarasılık',meaning:'تناص',sentence:'Yazar, eski bir anlatıya gönderme yaparak yeni metne ikinci bir katman ekliyor.',translation:'يضيف الكاتب طبقة ثانية للنص الجديد عبر الإحالة إلى سرد قديم.',form:'kültürel gönderme',functionText:'تحليل الإحالات والتناص الثقافي.',task:'اجمع إحالات ثقافية من مقال واشرح كيف تغير فهمه.',example:'Göndermelerin hedef okur için ne ifade ettiğini değerlendirdim.|قيّمت ما تعنيه الإحالات للقارئ المستهدف.',dialogue:'A: Her okur bu göndermeyi anlar mı؟ — هل يفهم كل قارئ هذه الإحالة؟\nB: Kültürel birikime bağlı olarak değişebilir. — قد يختلف ذلك بحسب الخلفية الثقافية.'),
_Spec(unitId:'c2-u10',number:516,title:'تحليل خطاب الأزمات والمعلومات المضللة',goal:'تقييم الرسائل المتداولة أثناء الأزمات من حيث المصدر والدليل والتأطير.',rule:'تحقق من المصدر والتاريخ والسياق، وافصل الادعاء عن التفسير، وتجنب تضخيم غير المؤكد.',term:'yanıltıcı bilgi',meaning:'معلومات مضللة',sentence:'İddianın kaynağı doğrulanmadan kesin bir yargıya varılmamalıdır.',translation:'لا ينبغي الوصول إلى حكم قاطع قبل التحقق من مصدر الادعاء.',form:'kriz söylemi',functionText:'تقييم خطاب الأزمات ومصداقية الادعاءات.',task:'حلل ثلاث رسائل افتراضية وصنف ما يمكن التحقق منه وما لا يزال غير مؤكد.',example:'Bilginin doğrulanma düzeyini açıkça belirttim.|حددت بوضوح مستوى التحقق من المعلومة.',dialogue:'A: Bu haber kesin mi؟ — هل هذا الخبر مؤكد؟\nB: Kaynak ve tarih doğrulanmadan söyleyemeyiz. — لا يمكننا القول قبل التحقق من المصدر والتاريخ.'),
_Spec(unitId:'c2-u10',number:517,title:'مقارنة الخطاب الإعلامي والعلمي',goal:'تمييز اختلاف أهداف الخطاب ومعايير الدليل ودرجات اليقين.',rule:'قارن الجمهور والمصطلحات والمنهج والتحفظات، ولا تعتبر اختلاف الأسلوب تناقضاً بالضرورة.',term:'bilimsel ve medya söylemi',meaning:'الخطاب العلمي والإعلامي',sentence:'Bilimsel metin belirsizliği belirtirken haber başlığı sonucu kesinleştirebilir.',translation:'قد يذكر النص العلمي عدم اليقين بينما يحسم العنوان الصحفي النتيجة.',form:'söylem türleri',functionText:'مقارنة أنماط الخطاب ومعاييرها.',task:'قارن تغطية إعلامية وملخصاً علمياً للنتيجة نفسها.',example:'İki metnin kesinlik derecesini ve kanıt yapısını karşılaştırdım.|قارنت درجة اليقين وبنية الدليل في النصين.',dialogue:'A: Başlık neden daha kesin görünüyor؟ — لماذا يبدو العنوان أكثر جزماً؟\nB: Dikkat çekmek için ayrıntıları daraltmış olabilir. — ربما ضيّق التفاصيل لجذب الانتباه.'),
_Spec(unitId:'c2-u10',number:518,title:'بناء أطروحة نقدية متعددة المصادر',goal:'تركيب أطروحة تجمع مصادر متعارضة دون تسطيح اختلافها.',rule:'حدد الادعاء المركزي، وصنف المصادر، ووازن الأدلة، وبيّن حدود الاستنتاج.',term:'çok kaynaklı sav',meaning:'أطروحة متعددة المصادر',sentence:'Farklı kaynakları karşılaştırarak daha sınırlı ama savunulabilir bir sonuç geliştirdim.',translation:'طورت نتيجة أكثر تحديداً لكنها قابلة للدفاع عبر مقارنة مصادر مختلفة.',form:'eleştirel sentez',functionText:'تركيب نقدي للأدلة والمواقف.',task:'اكتب أطروحة مدعومة بأربعة مصادر متباينة وناقش حدودها.',example:'Kaynaklar arasındaki uyuşmazlıkları görünür kıldım.|أظهرت أوجه التعارض بين المصادر.',dialogue:'A: Çelişen kaynakları dışlayalım mı؟ — هل نستبعد المصادر المتعارضة؟\nB: Önce farklılıkların nedenini inceleyelim. — لنبحث أولاً سبب الاختلافات.'),
_Spec(unitId:'c2-u10',number:519,title:'إعداد ندوة أكاديمية نقدية',goal:'تنظيم ندوة تعرض مواقف متعددة وتدير النقاش وتوثق نتائجه.',rule:'حدد سؤالاً محورياً ومتحدثين متنوعين ومحاور زمنية وأسئلة نقدية وخلاصة متوازنة.',term:'akademik panel',meaning:'ندوة أكاديمية',sentence:'Panelin sonunda ortak noktaları ve açık kalan soruları özetledik.',translation:'لخصنا في نهاية الندوة نقاط الاتفاق والأسئلة التي بقيت مفتوحة.',form:'eleştirel tartışma',functionText:'إدارة ندوة أكاديمية متوازنة.',task:'خطط ندوة من ثلاثة متحدثين وأدر جلسة الأسئلة واكتب خلاصة.',example:'Tartışmanın farklı seslerini dengeli biçimde yansıttım.|عكست الأصوات المختلفة في النقاش بصورة متوازنة.',dialogue:'A: Sonuçta tek bir görüş mü sunalım؟ — هل نقدم رأياً واحداً في النهاية؟\nB: Uzlaşılan ve tartışmalı noktaları ayıralım. — لنفصل بين النقاط المتفق عليها والمختلف عليها.'),
_Spec(unitId:'c2-u10',number:520,title:'مشروع تحليل الخطاب المقارن',goal:'إنجاز دراسة مقارنة تجمع التأطير والحجاج والتناص ومصداقية المصدر.',rule:'اختر corpus محدوداً، وضع أسئلة تحليلية، ووثق الأمثلة، ثم قدم استنتاجات مقيدة بالأدلة.',term:'söylem araştırması',meaning:'بحث في الخطاب',sentence:'Çalışmada iki metnin dilsel tercihlerini ve toplumsal bağlamını birlikte inceledim.',translation:'درست في البحث الاختيارات اللغوية والسياق الاجتماعي لنصين معاً.',form:'karşılaştırmalı araştırma',functionText:'تنفيذ مشروع بحثي في تحليل الخطاب.',task:'أعد دراسة قصيرة من نصين مع جدول أدلة واستنتاجات ومراجع.',example:'Analizimi örnekler ve açık ölçütlerle destekledim.|دعمت تحليلي بأمثلة ومعايير واضحة.',dialogue:'A: Hangi metinleri seçtin؟ — أي نصوص اخترت؟\nB: Aynı konuyu farklı çerçevelerle ele alan iki metni. — نصين يتناولان الموضوع نفسه بإطارين مختلفين.'),
_Spec(unitId:'c2-u11',number:521,title:'تصميم بحث لغوي متقدم',goal:'تحويل سؤال لغوي واسع إلى سؤال بحث قابل للفحص.',rule:'حدد المتغيرات والمجتمع والبيانات وحدود الدراسة وأسئلة قابلة للإجابة.',term:'araştırma sorusu',meaning:'سؤال بحثي',sentence:'Araştırma sorusunu ölçülebilir ve sınırları belirli hâle getirdim.',translation:'جعلت سؤال البحث قابلاً للقياس ومحدد الحدود.',form:'araştırma tasarımı',functionText:'تصميم سؤال ومنهج بحثي.',task:'حوّل موضوعاً عاماً إلى سؤال بحث وحدد البيانات اللازمة.',example:'Araştırma kapsamını uygulanabilir biçimde sınırlandırdım.|حددت نطاق البحث بصورة قابلة للتنفيذ.',dialogue:'A: Konu çok geniş değil mi؟ — أليس الموضوع واسعاً جداً؟\nB: Soruyu daraltıp belirli bir veri kümesine odaklanalım. — لنضيق السؤال ونركز على مجموعة بيانات محددة.'),
_Spec(unitId:'c2-u11',number:522,title:'اختيار المنهج وأدوات جمع البيانات',goal:'اختيار أدوات تتناسب مع سؤال البحث ونوع البيانات.',rule:'وازن بين المقابلة والاستبانة والمدونة النصية والملاحظة، وناقش تحيز كل أداة.',term:'veri toplama aracı',meaning:'أداة جمع البيانات',sentence:'Araştırma sorusuna uygun veri toplama araçlarını karşılaştırdık.',translation:'قارنّا أدوات جمع البيانات المناسبة لسؤال البحث.',form:'yöntem seçimi',functionText:'مواءمة المنهج مع سؤال الدراسة.',task:'اختر منهجاً لدراسة استخدام صيغة لغوية وبرر اختيارك.',example:'Yöntemi araştırma sorusuyla uyumlu seçtim.|اخترت المنهج بما يتوافق مع سؤال البحث.',dialogue:'A: Her araştırmada anket kullanılır mı؟ — هل تستخدم الاستبانة في كل بحث؟\nB: Araştırma sorusuna göre araç değişir. — تتغير الأداة وفق سؤال البحث.'),
_Spec(unitId:'c2-u11',number:523,title:'تحليل المدونات اللغوية',goal:'استخدام المدونات لاستخراج الأنماط والتواتر والسياق.',rule:'تحقق من تمثيل المدونة، وصنف النتائج، وافحص الأمثلة يدوياً قبل التعميم.',term:'derlem çözümlemesi',meaning:'تحليل المدونات',sentence:'Derlemdeki sıklık verilerini bağlam örnekleriyle birlikte yorumladım.',translation:'فسرت بيانات التواتر في المدونة مع أمثلة سياقية.',form:'derlem temelli araştırma',functionText:'تحليل استعمال اللغة عبر المدونات.',task:'قارن استعمال تعبيرين في مدونة وحدد حدود البيانات.',example:'Sıklık değerlerini bağlamdan bağımsız yorumlamadım.|لم أفسر قيم التواتر بمعزل عن السياق.',dialogue:'A: En sık kullanım her zaman en uygun mu؟ — هل الاستعمال الأكثر شيوعاً هو الأنسب دائماً؟\nB: Tür ve bağlam da belirleyicidir. — النوع والسياق عاملان حاسمان أيضاً.'),
_Spec(unitId:'c2-u11',number:524,title:'تفسير النتائج الكمية والنوعية',goal:'دمج الأرقام والأنماط النوعية دون تجاوز ما تسمح به البيانات.',rule:'اعرض النتيجة ومجالها وحدودها، وقارن الشواهد ولا تخلط الارتباط بالسببية.',term:'karma yöntem',meaning:'منهج مختلط',sentence:'Nicel bulguları görüşme verileriyle birlikte yorumladık.',translation:'فسرنا النتائج الكمية مع بيانات المقابلات.',form:'karma veri analizi',functionText:'دمج البيانات الكمية والنوعية.',task:'حلل مجموعة بيانات صغيرة مع مقابلات وقدم تفسيراً حذراً.',example:'Bulguların kapsamını verinin sınırlarına göre belirledim.|حددت نطاق النتائج وفق حدود البيانات.',dialogue:'A: İki değişken birlikte artıyorsa biri diğerine neden mi olur؟ — إذا زاد متغيران معاً فهل يسبب أحدهما الآخر؟\nB: Korelasyon tek başına nedensellik göstermez. — الارتباط وحده لا يثبت السببية.'),
_Spec(unitId:'c2-u11',number:525,title:'توثيق المصادر والنزاهة الأكاديمية',goal:'توثيق الاقتباس وإعادة الصياغة والبيانات والقرارات البحثية.',rule:'ميز الاقتباس من التلخيص، وسجل المصدر الأصلي، وراجع الأمانة ودقة الإحالة.',term:'akademik dürüstlük',meaning:'النزاهة الأكاديمية',sentence:'Başkasının düşüncesini kendi ifademle aktarsam da kaynağı belirtirim.',translation:'حتى عندما أنقل فكرة شخص آخر بصياغتي أذكر المصدر.',form:'kaynak gösterme',functionText:'توثيق المصادر بأمانة.',task:'حرر فقرة بحثية وأضف إحالات دقيقة لكل فكرة مقتبسة.',example:'Kaynak zincirini ve alıntı sınırlarını kontrol ettim.|راجعت سلسلة المصادر وحدود الاقتباس.',dialogue:'A: Yeniden ifade etmek kaynak gerektirmez mi؟ — ألا تحتاج إعادة الصياغة إلى مصدر؟\nB: Fikir başkasına aitse kaynak gösterilmelidir. — إذا كانت الفكرة لشخص آخر فيجب ذكر المصدر.'),
_Spec(unitId:'c2-u11',number:526,title:'كتابة قسم المنهجية والنتائج',goal:'صياغة وصف قابل للتكرار للمنهج وعرض منظم للنتائج.',rule:'اكتب إجراءات واضحة، وحدد العينة والأدوات، واعرض النتائج دون خلطها بالمناقشة.',term:'yöntem ve bulgular',meaning:'المنهجية والنتائج',sentence:'Yöntem bölümünde veri seçimini ve çözümleme adımlarını ayrıntılandırdım.',translation:'فصلت اختيار البيانات وخطوات التحليل في قسم المنهجية.',form:'araştırma raporu',functionText:'كتابة المنهجية والنتائج البحثية.',task:'اكتب قسم منهجية ونتائج لدراسة لغوية مصغرة.',example:'Yöntemi başka bir araştırmacının izleyebileceği biçimde yazdım.|كتبت المنهجية بصورة يستطيع باحث آخر اتباعها.',dialogue:'A: Sonuçları yorumlayalım mı؟ — هل نفسر النتائج؟\nB: Önce bulguları tarafsız biçimde sunalım. — لنعرض النتائج بموضوعية أولاً.'),
_Spec(unitId:'c2-u11',number:527,title:'مناقشة النتائج والقيود',goal:'ربط النتائج بالأدبيات وتفسيرها مع الاعتراف بالقيود.',rule:'قارن بالدراسات السابقة، وناقش تفسيرات بديلة، وحدد ما لا تثبته الدراسة.',term:'araştırma sınırlılığı',meaning:'قيد بحثي',sentence:'Örneklemin sınırlı olması sonuçların genellenmesini zorlaştırıyor.',translation:'تجعل محدودية العينة تعميم النتائج أكثر صعوبة.',form:'bulgu tartışması',functionText:'مناقشة النتائج وحدودها.',task:'اكتب مناقشة تتضمن تفسيرين بديلين وثلاثة قيود.',example:'Sınırlılıkları sonuçların değerini azaltmadan açıkladım.|أوضحت القيود دون الانتقاص من قيمة النتائج.',dialogue:'A: Sınırlılıkları yazmak çalışmayı zayıflatır mı؟ — هل كتابة القيود تضعف الدراسة؟\nB: Aksine, bulguların kapsamını dürüstçe gösterir. — على العكس، فهي تبين نطاق النتائج بأمانة.'),
_Spec(unitId:'c2-u11',number:528,title:'التحكيم العلمي والرد على المراجعين',goal:'تقييم بحث وفق معايير واضحة وصياغة رد مهني على الملاحظات.',rule:'صنف التعليقات إلى جوهرية وشكلية، ورد بالدليل، ووضح التعديلات أو أسباب عدم الأخذ بها.',term:'hakem değerlendirmesi',meaning:'تحكيم علمي',sentence:'Her hakem yorumuna metindeki değişiklik veya gerekçeli yanıtla karşılık verdim.',translation:'أجبت عن كل تعليق تحكيمي بتعديل في النص أو رد مبرر.',form:'hakem yanıtı',functionText:'الرد العلمي على المراجعات.',task:'اكتب خطاب رد على خمسة تعليقات مراجعين مع تحديد مواضع التعديل.',example:'Eleştirileri savunmaya geçmeden değerlendirdim.|قيّمت الانتقادات دون اتخاذ موقف دفاعي.',dialogue:'A: Her öneriyi kabul etmeli miyiz؟ — هل يجب قبول كل اقتراح؟\nB: Kanıta ve çalışmanın kapsamına göre karar vermeliyiz. — ينبغي أن نقرر وفق الدليل ونطاق الدراسة.'),
_Spec(unitId:'c2-u11',number:529,title:'العرض العلمي والدفاع عن البحث',goal:'تقديم نتائج الدراسة والدفاع عن المنهج والحدود أمام لجنة.',rule:'صغ قصة بحثية موجزة، ووضح الإضافة، واستعد للأسئلة عن العينة والتحليل والقيود.',term:'akademik savunma',meaning:'دفاع أكاديمي',sentence:'Çalışmanın katkısını ve sınırlılıklarını jüriye açıkça anlattım.',translation:'شرحت للجنة إسهام الدراسة وقيودها بوضوح.',form:'bilimsel sunum',functionText:'عرض البحث والدفاع عنه.',task:'قدم عرضاً بحثياً من عشر دقائق وأجب عن أسئلة نقدية.',example:'Savunmamı veriler ve yöntem kararlarıyla temellendirdim.|أسست دفاعي على البيانات والقرارات المنهجية.',dialogue:'A: En önemli katkı nedir؟ — ما أهم إسهام؟\nB: Önceki çalışmalarda görünmeyen örüntüyü göstermesi. — إظهار نمط لم يظهر في الدراسات السابقة.'),
_Spec(unitId:'c2-u11',number:530,title:'مشروع البحث اللغوي المتكامل',goal:'تنفيذ مشروع بحث من السؤال حتى التقرير والعرض والدفاع.',rule:'اجمع التصميم والبيانات والتحليل والكتابة والتوثيق والعرض في مسار متسق.',term:'bütünleşik dil araştırması',meaning:'بحث لغوي متكامل',sentence:'Araştırmayı tasarımdan sunuma kadar tutarlı bir yöntemle tamamladım.',translation:'أكملت البحث بمنهج متسق من التصميم حتى العرض.',form:'araştırma projesi',functionText:'إنجاز مشروع بحث لغوي كامل.',task:'أنجز بحثاً قصيراً مع ملخص ومنهج ونتائج ومناقشة ومراجع وعرض.',example:'Her aşamayı araştırma sorusuyla ilişkilendirdim.|ربطت كل مرحلة بسؤال البحث.',dialogue:'A: Projenin son kontrolünde neye bakacağız؟ — ما الذي نراجعه أخيراً في المشروع؟\nB: Tutarlılık, kaynaklar ve bulguların dayanağı. — الاتساق والمصادر وأساس النتائج.'),
_Spec(unitId:'c2-u12',number:531,title:'التواصل الدبلوماسي الدقيق',goal:'صياغة رسائل تراعي العلاقات الرسمية والحساسية والسياق.',rule:'وازن بين الوضوح والتحفظ، وحدد الأفعال الكلامية، وتجنب العبارات التي تخلق التزاماً غير مقصود.',term:'diplomatik dil',meaning:'لغة دبلوماسية',sentence:'Tarafların hassasiyetlerini gözeten dengeli bir ifade kullandık.',translation:'استخدمنا صياغة متوازنة تراعي حساسيات الأطراف.',form:'diplomatik iletişim',functionText:'التواصل الرسمي الحساس.',task:'اكتب ثلاث صيغ لرسالة واحدة بدرجات مختلفة من التحفظ.',example:'Mesajın tonunu ilişki ve bağlama göre ayarladım.|ضبطت نبرة الرسالة وفق العلاقة والسياق.',dialogue:'A: Bu ifade fazla kesin mi؟ — هل هذه العبارة حاسمة أكثر من اللازم؟\nB: Biraz daha ihtiyatlı bir seçenek kullanabiliriz. — يمكننا استخدام صيغة أكثر تحفظاً.'),
_Spec(unitId:'c2-u12',number:532,title:'إدارة التفاوض متعدد الثقافات',goal:'فهم اختلاف قواعد التواصل والتفاوض بين الثقافات.',rule:'لا تعمم الصور النمطية، واسأل عن تفضيلات الطرف، وراقب المباشرة والوقت وآليات القرار.',term:'kültürlerarası müzakere',meaning:'تفاوض بين الثقافات',sentence:'Karar alma biçimini anlamak için karşı tarafın beklentilerini sorduk.',translation:'سألنا عن توقعات الطرف الآخر لفهم طريقة اتخاذ القرار.',form:'kültürlerarası yetkinlik',functionText:'التفاوض مع مراعاة الاختلاف الثقافي.',task:'صمم محاكاة تفاوض بين مؤسستين مختلفتين في أسلوب التواصل.',example:'Varsayımlar yerine doğrudan açıklama istedim.|طلبت توضيحاً مباشراً بدلاً من الاعتماد على الافتراضات.',dialogue:'A: Sessizlik ne anlama geliyor؟ — ماذا يعني الصمت؟\nB: Bağlama göre değişir; varsayımda bulunmayalım. — يختلف بحسب السياق؛ لا نفترض.'),
_Spec(unitId:'c2-u12',number:533,title:'صياغة البروتوكولات والبيانات الرسمية',goal:'إنتاج بيانات رسمية دقيقة ومتوازنة ومتسقة مع الصلاحيات.',rule:'تحقق من الأسماء والصفات والتواريخ، وميز الموقف الرسمي من التوقع أو التفسير.',term:'resmî bildiri',meaning:'بيان رسمي',sentence:'Bildiride yalnızca doğrulanmış ve yetkili makamca onaylanmış bilgiler yer aldı.',translation:'تضمن البيان معلومات مؤكدة فقط ومعتمدة من الجهة المخولة.',form:'protokol metni',functionText:'صياغة البيانات الرسمية والبروتوكولية.',task:'حرر بياناً رسمياً ثم راجعه من حيث الدقة والصلاحيات والنبرة.',example:'Resmî metnin kapsamını ve onay zincirini doğruladım.|تحققت من نطاق النص الرسمي وتسلسل اعتماده.',dialogue:'A: Tahmini bilgi ekleyelim mi؟ — هل نضيف معلومات تقديرية؟\nB: Doğrulanmadıysa ayrı ve açık biçimde belirtilmeli. — إن لم تكن مؤكدة فيجب تمييزها بوضوح.'),
_Spec(unitId:'c2-u12',number:534,title:'التواصل أثناء المفاوضات الحساسة',goal:'إدارة الرسائل عند وجود خلافات ومصالح متعارضة.',rule:'افصل الموقف عن المصلحة، واستخدم أسئلة توضيحية، ووثق نقاط التفاهم دون مبالغة.',term:'hassas müzakere',meaning:'تفاوض حساس',sentence:'Önce tarafların temel çıkarlarını anlamaya çalıştık.',translation:'حاولنا أولاً فهم المصالح الأساسية للأطراف.',form:'müzakere dili',functionText:'إدارة الحوار في المفاوضات الحساسة.',task:'أدر جلسة تفاوض واكتب ملخصاً محايداً لنقاط التفاهم.',example:'Anlaşmazlığı kişiselleştirmeden ele aldım.|تناولت الخلاف دون تحويله إلى أمر شخصي.',dialogue:'A: Bu talebi reddedelim mi؟ — هل نرفض هذا الطلب؟\nB: Önce arkasındaki ihtiyacı anlayalım. — لنفهم أولاً الحاجة التي تقف وراءه.'),
_Spec(unitId:'c2-u12',number:535,title:'الوساطة وصناعة التوافق',goal:'تسهيل اتفاق دون فرض حل على الأطراف.',rule:'حدد القضايا المشتركة، واطلب خيارات، واختبر قابلية التنفيذ، وصغ اتفاقاً واضحاً.',term:'uzlaşma arabuluculuğu',meaning:'وساطة توافقية',sentence:'Tarafların kabul edebileceği seçenekleri birlikte geliştirdik.',translation:'طورنا معاً خيارات يمكن للأطراف قبولها.',form:'arabuluculuk',functionText:'بناء التوافق بين أطراف مختلفة.',task:'نفذ محاكاة وساطة واكتب اتفاقاً يتضمن مسؤوليات ومواعيد.',example:'Ortak zemini tarafların kendi ifadeleriyle tanımladım.|حددت الأرضية المشتركة بتعبيرات الأطراف نفسها.',dialogue:'A: Çözümü biz mi sunacağız؟ — هل نقدم الحل نحن؟\nB: Seçenekleri tarafların geliştirmesini kolaylaştıralım. — لنسهل على الأطراف تطوير الخيارات.'),
_Spec(unitId:'c2-u12',number:536,title:'إدارة فرق الخبراء الدولية',goal:'تنسيق فريق متعدد التخصصات والمواقع مع اختلاف المصطلحات والأولويات.',rule:'حدد المسؤوليات وواجهات العمل، ووحد تعريفات المخرجات، وأنشئ آلية قرار وتوثيق.',term:'uluslararası uzman ekibi',meaning:'فريق خبراء دولي',sentence:'Ekipte ortak terminoloji ve açık görev dağılımı oluşturduk.',translation:'أنشأنا في الفريق مصطلحات مشتركة وتوزيعاً واضحاً للمهام.',form:'uzman koordinasyonu',functionText:'تنسيق الخبراء عبر التخصصات.',task:'صمم ميثاق فريق دولي يحدد الأدوار والقرارات وآليات التواصل.',example:'Uzmanların katkılarını ortak hedeflerle ilişkilendirdim.|ربطت مساهمات الخبراء بالأهداف المشتركة.',dialogue:'A: Herkes aynı yöntemi mi kullanmalı؟ — هل يجب أن يستخدم الجميع المنهج نفسه؟\nB: Ortak standartlar ve uzmanlık alanları dengelenmeli. — ينبغي الموازنة بين المعايير المشتركة ومجالات الخبرة.'),
_Spec(unitId:'c2-u12',number:537,title:'صياغة اتفاقات متعددة الأطراف',goal:'كتابة اتفاق يحدد المصطلحات والالتزامات والاستثناءات وآليات المتابعة.',rule:'عرّف المصطلحات، وحدد الأطراف والمسؤوليات والجدول والتعديل وتسوية النزاع.',term:'çok taraflı anlaşma',meaning:'اتفاق متعدد الأطراف',sentence:'Anlaşmada yükümlülükleri ve uygulama takvimini açıkça tanımladık.',translation:'حددنا الالتزامات وجدول التنفيذ بوضوح في الاتفاق.',form:'anlaşma hükümleri',functionText:'صياغة بنود اتفاق متعدد الأطراف.',task:'اكتب مسودة اتفاق من خمسة بنود مع آلية مراجعة وتسوية خلاف.',example:'Her yükümlülüğü sorumlu taraf ve tarihle eşleştirdim.|ربطت كل التزام بالطرف المسؤول والتاريخ.',dialogue:'A: Belirsiz ifadeler sorun yaratır mı؟ — هل تسبب العبارات الغامضة مشكلات؟\nB: Uygulamada farklı yorumlara yol açabilir. — قد تؤدي إلى تفسيرات مختلفة عند التطبيق.'),
_Spec(unitId:'c2-u12',number:538,title:'التواصل الاستراتيجي في المؤسسات الدولية',goal:'مواءمة الرسائل مع الأهداف والجمهور والمخاطر المؤسسية.',rule:'حدد الرسالة المحورية والقنوات والمتحدثين ومؤشرات الفهم والتفاعل.',term:'uluslararası stratejik iletişim',meaning:'تواصل استراتيجي دولي',sentence:'Mesajları farklı paydaşlara göre uyarlarken temel tutarlılığı koruduk.',translation:'حافظنا على الاتساق الأساسي مع تكييف الرسائل لمختلف أصحاب المصلحة.',form:'paydaş iletişimi',functionText:'إدارة التواصل مع أصحاب المصلحة الدوليين.',task:'ضع خطة تواصل لبرنامج دولي مع رسائل وقنوات ومؤشرات.',example:'Her paydaş için mesajın amacını netleştirdim.|وضحت هدف الرسالة لكل صاحب مصلحة.',dialogue:'A: Her gruba aynı metni mi gönderelim؟ — هل نرسل النص نفسه لكل مجموعة؟\nB: Ana mesaj aynı kalmalı, sunum uyarlanabilir. — تبقى الرسالة الأساسية نفسها ويمكن تكييف طريقة عرضها.'),
_Spec(unitId:'c2-u12',number:539,title:'إدارة الخلافات المؤسسية العابرة للحدود',goal:'تحليل خلاف مؤسسي متعدد الأطراف وصياغة مسار احتواء.',rule:'حدد الوقائع والتفسيرات والمصالح، ثم اتفق على قناة اتصال وخطوات تحقق وتصعيد.',term:'sınır ötesi uyuşmazlık',meaning:'نزاع عابر للحدود',sentence:'Uyuşmazlığı çözmek için ortak doğrulama ve iletişim süreci kurduk.',translation:'أنشأنا عملية مشتركة للتحقق والتواصل لحل النزاع.',form:'kurumsal uyuşmazlık',functionText:'إدارة الخلافات المؤسسية الدولية.',task:'حلل حالة نزاع افتراضية وصمم خطة اتصال وتسوية مرحلية.',example:'Tarafların farklı hukuk ve uygulama çerçevelerini dikkate aldım.|أخذت في الاعتبار الأطر القانونية والتطبيقية المختلفة للأطراف.',dialogue:'A: Hemen resmî itiraz mı yapalım؟ — هل نقدم اعتراضاً رسمياً فوراً؟\nB: Önce olguları ve çözüm kanallarını netleştirelim. — لنوضح الوقائع وقنوات الحل أولاً.'),
_Spec(unitId:'c2-u12',number:540,title:'المشروع الختامي المتقدم لمستوى C2',goal:'دمج التحليل والبحث والتواصل والترجمة والقيادة في مشروع واحد.',rule:'قدم ملفاً متعدد الأجزاء يبرهن على الدقة والمرونة والاستقلالية، مع تقييم نقدي للقرارات.',term:'C2 bitirme projesi',meaning:'المشروع الختامي C2',sentence:'Dilsel, akademik ve kurumsal becerilerimi tek bir kapsamlı projede birleştirdim.',translation:'جمعت مهاراتي اللغوية والأكاديمية والمؤسسية في مشروع شامل واحد.',form:'ileri yeterlik',functionText:'إثبات الكفاءة المتقدمة المتكاملة.',task:'أنجز مشروعاً نهائياً يضم بحثاً وعرضاً ومفاوضة ونصاً مترجماً وتقييماً ذاتياً.',example:'Kararlarımı kanıtlarla gerekçelendirip süreci eleştirel biçimde değerlendirdim.|بررت قراراتي بالأدلة وقيّمت العملية بصورة نقدية.',dialogue:'A: C2 düzeyinde başarı neyle ölçülür؟ — بماذا يقاس النجاح في مستوى C2؟\nB: Karmaşık durumlarda bağımsız ve etkili dil kullanımıyla. — باستخدام اللغة باستقلالية وفاعلية في المواقف المعقدة.'),
 ].map(_build).toList(growable:false);
}
